#define SIN(x) ((sin(x) + 1.) / 2.)
#define FRACTAL_RECURSIVE_SCALE 3.0
#define BLUR 1./iResolution.y
#define PI 3.14159

float shapePattern(vec2 uv, float time, int type)
{
    uv -= 0.5;  // Center the coordinates
    float dist = length(uv);
    float angle = atan(uv.y, uv.x);

    if (type == 0)  // Starburst shape
    {
        float outerRadius = 0.15 + 0.15 * SIN(time);
        float innerRadius = 0.25 + 0.1 * abs(SIN(time * 2.0));
        float numSpikes = 8.0;
        float spikeShape = 0.5 + 0.5 * cos(numSpikes * angle);
        float boundary = mix(innerRadius, outerRadius, spikeShape);
        return smoothstep(boundary + BLUR, boundary - BLUR, dist);
    }
    #define NLines (20.*4.)
    else if (type == 1)  // spiral
    {
        return 1.0 + 0.3 * sin(NLines * angle + time * 2.0 + dist * 8.0 * 8.0);
    }
    else if (type == 2)  // un-spiral
    {
        return 1.0 + 0.25 * sin(-NLines * angle + time * 2.0 + dist * 8.0 * 8.0);
    }
    else if (type == 3)  // Diamond pattern
    {
        float diamond = abs(fract(uv.x) - 0.5) + abs(fract(uv.y) - 0.5);
        return smoothstep(0.5 - BLUR, 0.5 + BLUR, diamond);
    }

    return 0.0;  // Default pattern (empty)
}

#define fractalMask(shapeType, uv, t, mxIt, recursiveScale, timeShift, baseColor, highlightColor, O) \
{ \
    float time = t; \
    int maxIterations = mxIt; \
    vec3 _color = baseColor; \
    vec2 _uv = uv; \
    for (int i = 0; i < maxIterations; i++) \
    { \
        ivec2 cell = ivec2(floor(_uv * recursiveScale)); \
        if (cell == ivec2(1, 1)) \
        { \
            float maskValue = shapePattern(fract(_uv * recursiveScale), time, shapeType); \
            _color = mix(highlightColor, _color, 1.0 - maskValue); \
        } \
        _uv = fract(_uv * recursiveScale); \
        time += timeShift; \
    } \
    O = _color; \
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy;

    float zoomT = 0.5 + 0.5*sin(iTime/10.);
    if (iMouse.z>0.) zoomT = iMouse.x/iResolution.x;
    float zoom = mix(0.5, 50., zoomT);
    //zoom = 1.;
    uv = (uv - 0.5) / pow(zoom,2.) + 0.5;

    uv -= 0.5;
    uv.x *= iResolution.x / iResolution.y;
    uv += 0.5;

    vec3 diamondFractalColor;
    fractalMask(3, uv, iTime, 12, FRACTAL_RECURSIVE_SCALE, -0.2, 
                vec3(0.0, 0.0, 0.0),
                0.25 + 0.25 * sin(PI/2.+time+uv.xyx+vec3(0.,2.,4.)),
                diamondFractalColor);

    vec3 starburstFractalColor;
    fractalMask(0, uv, iTime, 10, FRACTAL_RECURSIVE_SCALE, 0.5,
                vec3(0., 1., 1.),
                0.5 + 0.5*cos(time+uv.xyx+vec3(0,2,4)),
                //0.5 + 0.5 * cos((PI*2.+time)*2.+uv.yxy+vec3(4.,0.,2.)),
                starburstFractalColor);

    float spiralOverlay = shapePattern(uv, -iTime, 1) - shapePattern(uv, -iTime, 2);

    vec3 mixedColor = mix(starburstFractalColor, diamondFractalColor, 20.);// 0.7 + 0.3 * SIN(iTime));
    vec3 finalColor;// = mixedColor * vec3(1.-spiralOverlay);
    finalColor = mixedColor * vec3(spiralOverlay);

    fragColor = vec4(finalColor, 1.0);
}
